/// Per-glyph advances in pixels, regular weight, indexed by `glyph_index(c)`.
pub const ADVANCE_FHD: [u8; 95] = [9, 9, 12, 20, 18, 23, 20, 6, 11, 11, 16, 18, 7, 9, 9, 13, 17, 17, 17, 17, 17, 17, 17, 17, 17, 17, 8, 7, 16, 17, 17, 15, 24, 21, 20, 20, 21, 18, 17, 21, 22, 9, 17, 20, 17, 24, 22, 22, 20, 22, 19, 19, 19, 20, 20, 24, 20, 19, 19, 9, 13, 9, 13, 15, 11, 17, 18, 17, 18, 17, 11, 18, 17, 8, 8, 16, 8, 24, 17, 18, 18, 18, 11, 16, 11, 17, 15, 23, 16, 15, 16, 11, 9, 11, 21];

#[inline]
pub fn glyph_index(c: u8) -> Option<usize> {
    if (FIRST_CHAR..=LAST_CHAR).contains(&c) {
        Some((c - FIRST_CHAR) as usize)
    } else {
        None
    }
}

#[inline]
pub fn advance_of(c: u8) -> usize {
    match glyph_index(c) {
        Some(i) => ADVANCE_FHD[i] as usize,
        None => FALLBACK_ADVANCE,
    }
}

#[inline]
pub fn pixel(c: u8, col: usize, row: usize) -> bool {
    if col >= GLYPH_W || row >= GLYPH_H {
        return false;
    }
    match glyph_index(c) {
        Some(i) => (FONT_FHD[i * GLYPH_H + row] >> (GLYPH_W - 1 - col)) & 1 == 1,
        None => false,
    }
}

#[inline]
pub fn coverage(c: u8, col: usize, row: usize) -> u32 {
    if col >= GLYPH_W || row >= GLYPH_H {
        return 0;
    }
    match glyph_index(c) {
        Some(i) => {
            let row_words = FONT_COV_FHD[i * GLYPH_H + row];
            let seg = col / 8;
            let offset_in_seg = col % 8;
            let shift = 4 * (7 - offset_in_seg);
            ((row_words[seg] >> shift) & 0xF) as u32
        }
        None => 0,
    }
}

#[inline]
pub fn measure(text: &[u8]) -> usize {
    let mut w = 0usize;
    for &c in text {
        w += advance_of(c);
    }
    w
}

#[inline]
pub fn line_height() -> usize {
    GLYPH_H
}

#[inline(always)]
pub fn blend(fg: u32, bg: u32, alpha: u8) -> u32 {
    if alpha == 255 {
        return fg;
    }
    if alpha == 0 {
        return bg;
    }
    let a = alpha as u32;
    let inv_a = 255 - a;
    let fr = (fg >> 16) & 0xFF;
    let fg_c = (fg >> 8) & 0xFF;
    let fb = fg & 0xFF;

    let br = (bg >> 16) & 0xFF;
    let bg_c = (bg >> 8) & 0xFF;
    let bb = bg & 0xFF;

    // Optical gamma-correct blending (gamma ≈ 2.0 luminous square curve)
    // Eliminates dark fringes and crushed midtones on OLED and high-DPI panels
    let r2 = (fr * fr * a + br * br * inv_a) / 255;
    let g2 = (fg_c * fg_c * a + bg_c * bg_c * inv_a) / 255;
    let b2 = (fb * fb * a + bb * bb * inv_a) / 255;

    let r = r2.isqrt() as u8;
    let g = g2.isqrt() as u8;
    let b = b2.isqrt() as u8;

    0xFF00_0000 | ((r as u32) << 16) | ((g as u32) << 8) | (b as u32)
}

#[inline(always)]
pub fn test_text(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    text: &[u8],
    color: u32,
) -> Option<u32> {
    if text.is_empty() {
        return None;
    }
    let dy = y.checked_sub(y0)?;
    if dy >= GLYPH_H {
        return None;
    }
    let dx = x.checked_sub(x0)?;
    let mut pen = 0usize;
    for &c in text {
        let adv = advance_of(c);
        if dx < pen + adv {
            let col = dx - pen;
            return if pixel(c, col, dy) {
                Some(color)
            } else {
                None
            };
        }
        pen += adv;
    }
    None
}

#[inline(always)]
pub fn test_text_aa(
    x: usize,
    y: usize,
    x0: usize,
    y0: usize,
    text: &[u8],
    color: u32,
    bg: u32,
) -> Option<u32> {
    if text.is_empty() {
        return None;
    }
    let dy = y.checked_sub(y0)?;
    if dy >= GLYPH_H {
        return None;
    }
    let dx = x.checked_sub(x0)?;
    let mut pen = 0usize;
    for &c in text {
        let adv = advance_of(c);
        if dx < pen + adv {
            let col = dx - pen;
            match coverage(c, col, dy) {
                0 => return None,
                15 => return Some(color),
                level => return Some(blend(color, bg, (level * 17) as u8)),
            }
        }
        pen += adv;
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_baseline() {
        assert!(BASELINE < GLYPH_H);
        assert!(CAP_TOP < BASELINE);
        assert!(DESCENDER >= BASELINE);
    }

    #[test]
    fn test_coverage_agrees_with_pixel() {
        for c in FIRST_CHAR..=LAST_CHAR {
            for row in 0..GLYPH_H {
                for col in 0..GLYPH_W {
                    let ink = pixel(c, col, row);
                    let level = coverage(c, col, row);
                    assert!(level <= 15, "coverage level out of range");
                    assert_eq!(ink, level >= 8,
                        "pixel/coverage disagree at {:?} col {} row {}",
                        c as char, col, row);
                }
            }
        }
    }

    #[test]
    fn test_digit_tabular_widths() {
        for d in b'0'..=b'9' {
            assert_eq!(advance_of(d), 17, "digit advance must be exactly 17");
        }
    }

    #[test]
    fn test_proportional_widths() {
        let adv_i = advance_of(b'i');
        let adv_m = advance_of(b'm');
        let adv_w = advance_of(b'W');
        assert!(adv_m > adv_i, "m should advance more than i");
        assert!(adv_w > adv_i, "W should advance more than i");
    }

    #[test]
    fn test_aa_uses_intermediate_tones() {
        let mut distinct = [false; 16];
        for c in FIRST_CHAR..=LAST_CHAR {
            for row in 0..GLYPH_H {
                for col in 0..GLYPH_W {
                    let level = coverage(c, col, row) as usize;
                    distinct[level] = true;
                }
            }
        }
        let tones = distinct.iter().filter(|&&d| d).count();
        assert!(tones >= 6, "only {} distinct edge tones; a 16-step ramp should span many more", tones);
    }
}

